import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { SellerActiveComponent } from './seller-active.component';

const routes: Routes = [{ path: '', component: SellerActiveComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class SellerActiveRoutingModule { }
